 const onsets=()=>{const m=mediaRef.current.find(m=>m.id===selectedMedia)??currentSource;if(!m){notify('Select a media source first.','error');return;}const events=m.analysis?.onsets??(m as Media&{audioMetrics?:{onsets:number[]}}).audioMetrics?.onsets??[];if(!events.length){notify('No threshold-based energy onsets found in this audio. No beat markers were fabricated.','info');return;}editor.operation(p=>{let next=p;const c=p.clips.find(c=>c.mediaId===m.id);for(const at of events.slice(0,Math.max(0,200-p.markers.length))){if(c&&at>=c.in&&at<c.out)next=addMarker(next,c.start+(at-c.in)/c.speed,'Audio energy onset (approx.)');}return next;});notify('Approximate energy-onset markers added; review musical timing.','success');};
